-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExa5203abf4903$doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf$CODExa5203abf4903$,$CODEx700ca5abd974$NEPAL CITIZENSHIP ACT 2063 (2006)$CODEx700ca5abd974$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2063,2006,10,$CODEx58f26a103164$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "NEPAL CITIZENSHIP ACT 2063 (2006) \nDate of Authentication and publication   \n10 Mangsir 2063 (26 Nov 2006)", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Amended by some Nepalese Acts Amendment Act ,20 64  2064.5.9", "content": "Act No. 25 of the year 2063 (i.e. 2006)  \nAn Act Made to Amend and Consolidate Laws Relating to Citizenship : \nPreamble: Whereas the sovereignty and state authori ty is vested on the Nepalese people \nas the result of the popular  movement; \n Whereas, as per the commitment mentioned in 'Decla ration of the  House of \nRepresentatives 2063 (2006) that  Nepalese citizens hip were facing difficulties in \nacquiring citizenship certificate in the past and b ased on the political understanding made \non 22 kartik 2063 (Nov 8th 2006),  \n     Whereas, it is expedient to amend and consolid ate the laws relating to citizenship \nregarding acquisition termination and other necessary provisions,    \n   Now, therefore, be it enacted by the House of Re presentatives in the First Year of \nthe Proclamation of the House of Representatives, 2063 (2006).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title and Commencement:   (1) This Act may be called \"Nepal", "content": "Citizenship Act 2063 (2006)\". \n(2) This Act shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definition:  Unless the subject or context otherwise requires, in this Act:", "content": "(a) \"Minor\"  means a person who has not attained th e age of 16 years. \n(b)  \"Person\" means natural person. \n(c)  \"Prescribed\" or \" as Prescribed\" means prescri bed or as prescribed in the \nRules made under this Act. \n3. \nAcquisition of Nepali Citizenship by descent : (1) A person born at the time \nwhen his/her father or mother is a citizen of Nepal , shall be a citizen of Nepal by \ndescent. \n(2) Whatever may be written in Sub-section (1), a c hild born out of \nwedlock by a Nepali female citizen to a foreign nat ional shall be in accordance \nwith Section 5, Sub-section  (2). \n(3) Every child found in the territory of Nepal, wh ose paternal and maternal \naddresses are undetermined, shall be considered a c itizen of Nepal by descent until \nhis/her father or mother are found.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Acquisition of Nepali Citizenship by Birth  : (1) Any person born before", "content": "2046 Chaitra 31, Bikram Sambat (i.e. 13, April, 199 0 A.D.) within the territory of \nNepal and having domiciled permanently in Nepal sha ll be deemed a citizen of \nNepal by birth. \n(2) A person desiring to obtain citizenship certifi cate pursuant to Sub-\nsection (1) shall have to apply before holding of t he election for Constituent \nAssembly and the procedure for granting of the Citi zenship Certificate shall be as \nprescribed. \n(3) In case a person, due to certain reasons, could  not submit his \napplication within the period specified in Sub-sect ion (1) may apply as prescribed \nwithin two years from the commencement of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Acquisition of Citizenship by Naturalization :  (1) A foreign women", "content": "married to a citizen of Nepal desiring to obtain ci tizenship of Nepal shall have to \nsubmit an application in the prescribed form to the  designated officer. On \nsubmitting such application she has to produce the marriage relationship document \nwith the citizen of Nepal and also evidence to show  the initiation of procedure for \nrenunciation of own's foreign citizenship. \n(2) A child born to a Nepali female citizen from ma rriage with a foreign \ncitizen in Nepal and having permanent domicile in N epal may be granted \nnaturalized citizenship as prescribed, provided the  child has not acquired the \ncitizenship of the foreign country on the basis of the citizenship of his/her father. \n(3) A person desiring to acquire naturalized citize nship pursuant to Sub-\nsection (2) shall have to submit an application wit h the following documents to the \ndesignated authority:  \n(a) Duplicate copy of the citizenship certificate o f the mother, \n(b) Recommendation by concerned Municipality or Vil lage \nDevelopment Committee certifying the birth and perm anent \nresidency in Nepal, \n(c) Evidence to show that foreign citizenship has n ot been acquired \nbased on the citizenship of the father. \n(4)  The Government of Nepal may grant naturalized citizenship as \nprescribed to those foreign citizens, who have cont ributed specially for the \nupliftment of science, philosophy, art, literature,  world peace, human welfare or \nNepalese industry, finance or social development an d have fulfilled the following \nconditions or status : \n(a)  who is able to read and write Nepali or any ot her language in \npractice in Nepal. \n(b) who is engaged in any occupation and domiciled in Nepal. \n(c) who has renounced or declared such renunciation  of the citizenship \nof the other country. \n(d) who has resided in Nepal for a minimum period o f 15 years. \n(e) who is a citizen of the country where there is provision of the law or \npractice to grant naturalized citizenship to Nepalese. \n(f) who bears good moral character \n(g) who is mentally fit and healthy. \n(5)  Whatever may have been written is Sub-section (4), from among the \nissues of the person, the child born to the person prior to that person having \nacquired citizenship by naturalization may also acq uire Nepalese citizenship by \nnaturalization as prescribed form. \n(6)  Any person acquiring citizenship by naturaliza tion under this \nSection shall take an oath as mentioned in the sche dule and awarded the Nepalese \ncitizen certificate in the prescribed form and such  person shall be naturalized \ncitizen of Nepal from the date of receiving such certificate.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Award of Honorary Nepalese Citizenship : Notwithstanding  any thing", "content": "mentioned in Section 5, the Government of Nepal may  award Honorary Nepalese \nCitizenship to any internationally renowned person.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Citizenship in the case of accession of territory :  When any part of territory", "content": "is integrated with Nepal, persons residing in such acceded territory shall be \nconsidered citizens of Nepal, from the date Governm ent of Nepal publishes a \nnotification as prescribed in the Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Filing of Application to obtain Citizenship Certifi cate  :  (1)  A person", "content": "attaining the age of 16 years desiring to acquire c itizenship of Nepal by descent \npursuant to Section 3, shall have to file an applic ation in the prescribed form along \nwith copies of the following documents to the designated authority: \n(a) Nepalese Citizenship Certificate of descendants  of \nrelatives within three generations from paternal or  \nmaternal or self side. \nProvided that , this provision shall not be applica ble to \nNepalese female citizen married to a foreigner. \n(b) Recommendation from the concerned Village Devel opment \nor Municipality certifying the place of birth and relationship. \n(2)  A person attaining the age of 16 years desirin g to acquire Nepalese \nCitizenship Certificate by virtue of birth pursuant  to Section 4 shall have to file an \napplication in the prescribed form along with copies of the following documents to \nthe designated authority. \n(a) Recommendation from the concerned Village Devel opment \nCommittee or Municipality certifying the birth in N epal and \nresiding permanently in Nepal. \n(b)  An evidence showing Land Ownership Certificate  in the \nname of self or family or Certificate of Land Tilli ng Right or \nproof of house or listing of name or the name of fa ther or \nmother in the Voters' list prepared by the Election  \nCommission. \n(3) On receipt of the applications pursuant to Sub- section (1) or (2), the \ndesignated authority shall award the Nepalese Citiz enship Certificate, after \nevaluating and based on evidence as produced. \n(4) In the circumstance, where a person could not s ubmit the evidences \nalong with the application as prescribed in Sub-sec tion (1) and (2), the designated \nauthority may award the Nepalese Citizenship Certif icate based on the spot \ninvestigation and on the basis of identification at  the time of spot investigation by \nat least three persons having obtained Nepalese Cit izenship Certificate and \nresiding in the same Ward and are acquainted with the applicant. \n(5) While conducting the spot investigating in acco rdance with Sub-\nsection (iv), the applicant must have been born in Nepal and stated clearly the fact \nof having lived in a permanent manner. \n(6) On investigation and evaluation pursuant to Sub -section (3) or (4), if \nany applicant is not found have been qualified to b e awarded the Nepalese \nCitizenship Certificate, one shall be duly notified  of the decision within the \nprescribed period.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Authority to issue Citizenship Certificate  :  The authority to issue Nepalese", "content": "Citizenship Certificate by descent, on the basis of  birth or by naturalization, shall \nbe vested on the designated authority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Termination of Nepalese Citizenship  (1) Any citizen of Nepal who", "content": "voluntarily acquires the citizenship of any foreign  country shall automatically lose \nthe citizenship of Nepal. \n(2) The designated authority shall register the not ice submitted by a \ncitizen of Nepal, who notifies in the prescribed fo rm of renunciation of the \nCitizenship of Nepal and the citizenship of that pe rson shall be terminated from \nthe date such notice has been duly registered. \n(3) Any person who has been divested of Nepalese ci tizenship pursuant \nto Section 14, shall be deemed to have lost his citizenship from that date. \n(3) If any person who is in a status of acquiring t he citizenships of Nepal \nand a foreign country concurrently, such person sha ll have to choose the \ncitizenship of any one country within two years aft er attaining the age of 16 years. \nFailure to choose the citizenship in this manner sh all be deemed for that person to \nhave lost his Nepalese citizenship on expiry of that specified period. \n(4) In case any question arises as to whether a Nep alese citizen has acquired a \nforeign citizenship or not, the designated authorit y shall make his \ndecision pursuant to the prevailing laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Re-acquisition of Nepalese Citizenship  : Any Citizen of Nepal who has", "content": "acquired foreign citizenship returns to reside in Nepal and submits a notification to \nthe designated authority the evidence of renunciati on of foreign citizenship shall \nbe reinstated the Nepalese citizenship from the date of registering such evidence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Revocation of Citizenship Certificate  :   The designated authority shall", "content": "revoke such Citizenship Certificate of any Nepalese  citizen, if it is proven that \nsuch citizenship had been obtained on submission of false documentation.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Two Citizenship Certificates not to be acquired : No person shall acquire", "content": "more that one citizenship certificate. \nProvided that, there shall be no objection to issue another citizenship certificate by \nthe concerned office on the basis of change of resi dency, if any person so desires, \nafter due withdrawal of the first issued citizenship certificate.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Deprivation from Nepalese Citizenship .  (1) The Government of Nepal may", "content": "issue directives to cancel the Nepalese Citizenship  Certificate and to divest \nNepalese citizenship of any foreign person who has been found proven to have \nfraudulently acquired Nepalese citizenship on submi ssion of false documents \nand declaration. \n(2) Any person whose Nepalese Citizenship has been divested by a \ndirective issued by the Government of Nepal in acco rdance with this section may \nfile an appeal to the concerned Appellate Court within thirty-five days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Records of Citizenship Certificates to be maintaine d : The system of", "content": "maintaining the records of Nepalese Citizenship Cer tificates shall be as  \nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Rights. duties and liabilities not to absolve  : No citizen of Nepal whose", "content": "citizenship in terminated for any reason, shall not  be deemed to have been \nabsolved of the rights, duties and liabilities incu rred in relation to any act done \nduring the period the person was a citizen of Nepal , only by reason of termination \nof the citizenship.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Correction of the Particulars  :  ∇∇ ∇∇  (1) Any person desiring to correct his/her", "content": "caste or age for being differently mentioned in the academic certificate to that of the \ncitizenship certificate or correct the minor mistak es in the citizenship certificate \n,shall have to provide for an application with nece ssary evidence to the designated \nauthority.  \nClarification \n : For the purpose of this section 'minor' mistake m eans the non \nsubstantial details the citizenship certificate to mean 'Kumari' \"Devi\" \"bahadur\" \n                                                             \n∇  Amended by some Nepalese Acts Amendment Act ,2064 \n\"Prasad\" like words being added or not mentioned or  difference in 'Aakar or Ikar \n(speccific grammatical error in devanagari) or other minor mistake of that type. \n(2) The designated authority on receipt of the appl ication pursuant to \nSub-section (1) shall conduct an enquiry with witne sses as necessary and together \nwith evidences obtained from such person shall make  the due correction and may \ngrant another citizenship certificate after withdra wing the citizenship certificate \nawarded previously. \n(3) The designated authority on receipt of the appl ication by a married \nor divorced woman for amendment of her family name,  address or other \nparticulars, may after verifying the necessary fact s grant another citizenship \ncertificate with amended family name, address or pa rticulars and withdraw the \nprevious citizenship certificate.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Revision : (1) Notwithstanding anything provided for in this A ct, any person", "content": "who is aggrieved by a decree issued by a designated  authority in accordance \nwith this Act, may file a petition within thirty fi ve days from the date such decree \nwas issued with the Government of Nepal for revision of such decree. \n(2) On receipt of the petition pursuant to Sub-sect ion (1), the \nGovernment of Nepal may obtain a report from the de signated authority issuing \nthe decree and after reviewing the report may give its verdict or issue a decree and \nsuch verdict or decree shall be final.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Publication of Name list :  Every year the names of the persons who have been", "content": "divested of Nepalese Citizenship pursuant to Sectio n 14 shall be published in the \nNepal gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Delegation of Authority  : (1) The Government of Nepal may delegate the", "content": "authority vested on itself pursuant to this Act to any officer in the Government of \nNepal. \nProvided that , the authority to divest from Nepale se Citizenship pursuant to \nSection 14 shall not be delegated. \n(2) The designated authority authorized to distribu te Citizenship \nCertificates pursuant to this Act may delegate the authority vested on him/her to \nany staff officer.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "punishment  : (1) Any foreign national who claims to be a Nepales e", "content": "citizen and acquires Nepalese citizenship by giving  false representation shall be \nsentenced to imprisonment from one year to five years or fined from fifty thousand \nrupees to one hundred thousand rupees or awarded bo th penalties. The citizenship \nacquired by false representation and having penaliz ed pursuant to this clause, the \ncitizenship thus acquired shall be automatically cancelled. \n(2) The person who was involved in the process of v erification or \nrecommendation in granting citizenship to any forei gn national on false particulars \nshall be sentenced to imprisonment from six months to three years or fined from \ntwenty five thousand rupees to fifty thousand rupees or awarded both penalties. \n(3) Any person who assists and begets false or forg ed Nepalese \nCitizenship Certificate and brings it in use shall be sentenced to imprisonment \nfrom one year to five years or fined from twenty th ousand rupees to one hundred \nthousand rupees or awarded both penalties. \n(4) Any person who alters or makes correction and a ssists in such \nundertaking on the particulars of the original citi zenship certificate shall be \nsentenced to imprisonment up to three months or fin ed up to ten thousand rupees \nor awarded both penalties. \n(5) Any person who furnishes and acquires citizensh ip certificate on \nfalse representation pursuant to Section 12 or the converted particulars pursuant to \nSection 17 is proven to be false or commits and Sec tion to commit any other \noffence in violation of this Act or the rules enacted under this Act shall be fined up \nto fifteen thousand Rupees. \n(6) The issuing authority of Nepalese Citizenship C ertificate \nintentionally or with mala fide  intention in violation of this Act and the Rules \nenacted under this Act issues Citizenship Certifica te or makes changes of the \nparticulars in the Citizenship Certificate, such au thority or employee shall be \nsubjected to departmental action as per the prevailing laws. \n(7) The person who undertakes or assists in any off ences punishable \nunder Sub-sections (1), (2) and (3) shall be awarde d half the punishment as \nmentioned in those Sub-sections.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Appointment of Citizenship Team :  (1) If the Government of Nepal", "content": "deems necessary, a Citizenship Certificate Distribu tion Team may be appointed to \ndistribute Citizenship Certificates. \n(2) The Team appointed pursuant to Sub-section (1) shall distribute \ncitizenship certificates within the directives auth orized by the Government of \nNepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Power to Frame Rules : The Government of Nepal may frame necessary Rules", "content": "for the fulfillment of the objectives of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Repeal and Savings:   (1) Nepal Citizenship Act. 2020 (1964) is hereby", "content": "repealed. \n(2) All acts performed or actions taken under the r epealed Act pursuant to \nsub-section (1) shall be deemed to have been perfor med or undertaken under this \nAct.", "children": []}]}]$CODEx58f26a103164$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
